SELECT DISTINCT sup.user_id AS userId, se.id AS employeeId, se.`name` AS name, se.gender, se.mobile_phone AS mobilePhone, sup.company_id AS orgId, cei.abbreviation AS orgName, sup.group_id AS postGroupId, pg.`name` AS postGroupName, sup.post_id AS postId, p.`name` AS postName FROM sys_user_post sup LEFT JOIN sys_employee se ON sup.user_id = se.user_id LEFT JOIN clinic_ext_info cei ON sup.company_id = cei.company_id LEFT JOIN post_group pg ON sup.group_id = pg.id LEFT JOIN post p ON sup.post_id = p.id
